    "owner",
    "resources",
    "waitingOn",
    "notes",
    "category",
    "engagementType",
    "contractStart",
    "contractEnd",
    "parentProjectId",
  ]);

  for (const field of fields) {
    if (!ALLOW.has(field)) continue;
    const newValue = normalized[field];
    const value =
      newValue === null || newValue === undefined ? null : String(newValue);
    const result = await updateProjectField({
      clientSlug: slug,
      projectName,
      field,
      newValue: value,
      updatedBy,
